use super::ascii::uppercase_first_ascii;
use super::case::downcase;

pub fn pluralize(input: &str) -> String {
    if input.is_empty() {
        String::new()
    } else {
        let mut output = String::with_capacity(input.len() + 1);
        output.push_str(input);
        output.push('s');
        output
    }
}

pub fn singularize(input: &str) -> String {
    input.strip_suffix('s').unwrap_or(input).to_string()
}

pub fn camelize(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut uppercase_next = false;

    for ch in input.chars() {
        if ch == '_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            if ch.is_ascii_lowercase() {
                output.push(ch.to_ascii_uppercase());
            } else {
                output.push(ch);
            }
            uppercase_next = false;
        } else {
            output.push(ch);
        }
    }

    output
}

pub fn underscore(input: &str) -> String {
    let mut output = String::with_capacity(input.len() * 2);

    for (index, ch) in input.chars().enumerate() {
        if ch.is_ascii_uppercase() {
            if index > 0 {
                output.push('_');
            }
            output.push(ch.to_ascii_lowercase());
        } else {
            output.push(ch);
        }
    }

    output
}

pub fn classify(input: &str) -> String {
    uppercase_first_ascii(&camelize(&singularize(input)))
}

pub fn tableize(input: &str) -> String {
    pluralize(&underscore(input))
}

pub fn humanize(input: &str) -> String {
    let mut output = String::with_capacity(input.len());

    for ch in input.chars() {
        if ch == '_' {
            output.push(' ');
        } else {
            output.push(ch);
        }
    }

    uppercase_first_ascii(&output)
}

pub fn dasherize(input: &str) -> String {
    input
        .chars()
        .map(|ch| if ch == '_' { '-' } else { ch })
        .collect()
}

pub fn parameterize(input: &str) -> String {
    let mut filtered = String::with_capacity(input.len());

    for ch in input.chars() {
        if ch.is_ascii_alphanumeric() || ch == ' ' {
            filtered.push(ch);
        }
    }

    downcase(&filtered)
        .chars()
        .map(|ch| if ch == ' ' { '-' } else { ch })
        .collect()
}

